<!DOCTYPE html>
<html lang="de">
<head>
    <meta charset="UTF-8">
    <title>Ball-Klick-Spiel</title>
    <style>
        body {
            margin: 0;
            background: #222;
            color: white;
            font-family: sans-serif;
            text-align: center;
            overflow: hidden;
            user-select: none;
        }
        #score {
            font-size: 24px;
            margin-top: 10px;
        }
        #ball {
            width: 50px;
            height: 50px;
            background: #ff3366;
            border-radius: 50%;
            position: absolute;
            cursor: pointer;
        }
    </style>
</head>
<body>
    <div id="score">Punkte: 0</div>
    <div id="ball"></div>

    <script>
        const ball = document.getElementById('ball');
        const scoreDisplay = document.getElementById('score');

        let score = 0;
        let x = 100, y = 100;
        let dx = 3, dy = 3;

        function update() {
            x += dx;
            y += dy;

            if (x <= 0 || x >= window.innerWidth - 50) dx *= -1;
            if (y <= 40 || y >= window.innerHeight - 50) dy *= -1;

            ball.style.left = x + 'px';
            ball.style.top = y + 'px';

            requestAnimationFrame(update);
        }

        ball.addEventListener('click', () => {
            score++;
            scoreDisplay.textContent = 'Punkte: ' + score;
            dx *= 1.1;
            dy *= 1.1;
            x = Math.random() * (window.innerWidth - 100);
            y = Math.random() * (window.innerHeight - 100) + 40;
        });

        update();
    </script>
</body>
</html>
```
Ein fangbares Ballspiel mit steigender Schwierigkeit.
